let out = {}, errors = null
try {
    // the JSON parameters; a SQL source only from the body, never the URL
    const parse = (name, fallback) => {
        const text = ec.web.secureRequestParameters[name] != null ? ec.web.secureRequestParameters[name] : context[name]
        if (text == null || text === '') return fallback
        try { return JSON.parse(String(text)) } catch (e) { throw new Error(name + ' is not JSON') }
    }
    const source = parse('sourceJson', null)
    if (source && source.type == 'sql' && ec.web.secureRequestParameters.sourceJson == null) throw new Error('A SQL source goes in the request body')
    out = ec.service.sync().name('org.moqui.dev.DatabaseServices.export#DataGrid').parameters({source, columns: parse('columnsJson', []), sort: parse('sortJson', []), filter: parse('filterJson', []), format: context.format || 'csv',
        location: context.location || null}).call() || {}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

const location = String(context.location || '')
const prefix = 'runtime://tmp/grid-export/' + ec.user.userId + '/'
const rest = location.startsWith(prefix) ? location.substring(prefix.length) : null
if (!ec.user.userId || rest == null || !rest || rest.split('/').some((segment) => segment == '..' || segment == '.' || segment == '')
        || !ec.resource.getLocationReference(location)?.getExists()) {
    ec.web.sendJsonError(404, ec.l10n.localize('Export not found'))
} else {
    const fileName = String(context.fileName || rest.split('/').pop()).replace(/[\\/"\r\n]/g, '_')
    ec.web.sendResourceResponse(location, false, fileName)
    // the export's own type (text/csv, the XLSX type), not one guessed from the name
    const types = ['text/csv', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']
    if (types.includes(String(context.contentType || ''))) ec.web.response.setContentType(String(context.contentType))
}

let out = {}, errors = null
try {
    // the JSON parameters; a SQL source only from the body, never the URL
    const parse = (name, fallback) => {
        const text = ec.web.secureRequestParameters[name] != null ? ec.web.secureRequestParameters[name] : context[name]
        if (text == null || text === '') return fallback
        try { return JSON.parse(String(text)) } catch (e) { throw new Error(name + ' is not JSON') }
    }
    const source = parse('sourceJson', null)
    if (source && source.type == 'sql' && ec.web.secureRequestParameters.sourceJson == null) throw new Error('A SQL source goes in the request body')
    out = ec.service.sync().name('org.moqui.dev.DatabaseServices.find#GridViews').parameters({}).call() || {}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

let out = {}, errors = null
try {
    // the JSON parameters; a SQL source only from the body, never the URL
    const parse = (name, fallback) => {
        const text = ec.web.secureRequestParameters[name] != null ? ec.web.secureRequestParameters[name] : context[name]
        if (text == null || text === '') return fallback
        try { return JSON.parse(String(text)) } catch (e) { throw new Error(name + ' is not JSON') }
    }
    const source = parse('sourceJson', null)
    if (source && source.type == 'sql' && ec.web.secureRequestParameters.sourceJson == null) throw new Error('A SQL source goes in the request body')
    out = ec.service.sync().name('org.moqui.dev.DatabaseServices.store#GridView').parameters({viewId: context.viewId || null, description: context.description || null, isShared: String(context.isShared) == 'true',
        sourceJson: String(ec.web.secureRequestParameters.viewSourceJson || ''), layoutJson: ec.web.secureRequestParameters.layoutJson || null}).call() || {}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

let out = {}, errors = null
try {
    // the JSON parameters; a SQL source only from the body, never the URL
    const parse = (name, fallback) => {
        const text = ec.web.secureRequestParameters[name] != null ? ec.web.secureRequestParameters[name] : context[name]
        if (text == null || text === '') return fallback
        try { return JSON.parse(String(text)) } catch (e) { throw new Error(name + ' is not JSON') }
    }
    const source = parse('sourceJson', null)
    if (source && source.type == 'sql' && ec.web.secureRequestParameters.sourceJson == null) throw new Error('A SQL source goes in the request body')
    out = ec.service.sync().name('org.moqui.dev.DatabaseServices.delete#GridView').parameters({viewId: String(context.viewId || '')}).call() || {}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

const term = String(context.term || '').toLowerCase()
const names = term ? ec.entity.getAllEntityNames().filter((name) => String(name).toLowerCase().includes(term)).slice(0, 50) : []
let related = null
const name = String(context.entityName || '')
try {
    let relatedName = null
    if (name.startsWith('DataDocument.')) {
        const doc = ec.entity.find('moqui.entity.document.DataDocument').condition('dataDocumentId', name.substring(13)).one()
        relatedName = doc ? doc.primaryEntityName : null
    } else if (name) {
        const master = ec.entity.find('moqui.entity.view.DbViewEntityMember').condition('dbViewEntityName', name).condition('entityAlias', 'MASTER').one()
        relatedName = master ? master.entityName : null
    }
    if (relatedName && ec.entity.isEntityDefined(relatedName))
        related = {entityName: relatedName, pkFieldNames: ec.entity.getEntityDefinition(relatedName).getPkFieldNames()}
} catch (e) { related = null }
ec.message.clearErrors()
ec.web.sendJsonResponse({entityNames: names, userId: ec.user.userId, canSql: ec.user.hasPermission('SQL_RUNNER_WEB'), related})

let out = {}, errors = null
try {
    // the JSON parameters; a SQL source only from the body, never the URL
    const parse = (name, fallback) => {
        const text = ec.web.secureRequestParameters[name] != null ? ec.web.secureRequestParameters[name] : context[name]
        if (text == null || text === '') return fallback
        try { return JSON.parse(String(text)) } catch (e) { throw new Error(name + ' is not JSON') }
    }
    const source = parse('sourceJson', null)
    if (source && source.type == 'sql' && ec.web.secureRequestParameters.sourceJson == null) throw new Error('A SQL source goes in the request body')
    out = ec.service.sync().name('org.moqui.calc.CalcServices.open#CalcDocument').parameters({definitionId: context.definitionId || null,
        workbookLocation: context.workbookLocation || null, source, columns: parse('columnsJson', []), sort: parse('sortJson', []),
        filter: parse('filterJson', []), title: context.title || null}).call() || {}
} catch (e) { errors = String(e.message || e) }
if (ec.message.hasError()) errors = ec.message.errorsString
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

let selection = null
try { selection = context.selectionJson ? JSON.parse(String(context.selectionJson)) : null } catch (e) { selection = null }
const out = ec.service.sync().name('org.moqui.calc.CalcServices.get#CalcCells').parameters({roomId: context.roomId, sheet: context.sheet,
    row: context.row, column: context.column, width: context.width, height: context.height,
    since: context.since || null, client: context.client || null, selection}).call() || {}
out.errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
// the block's JSON text with the room's last edit and the others beside its fields (the text is not parsed again), or
// only those when nothing changed since the view's edit
const head = {seq: out.seq == null ? null : Number(out.seq), peers: out.peers || []}
if (out.unchanged) ec.web.sendJsonResponse(Object.assign(head, {unchanged: true}))
else if (out.errors || !out.blockJson) ec.web.sendJsonResponse({errors: out.errors || 'No cells'})
else ec.web.sendTextResponse(JSON.stringify(head).slice(0, -1) + ',' + String(out.blockJson).slice(1), 'application/json', null)

let ops = []
try { ops = JSON.parse(String(ec.web.secureRequestParameters.opsJson != null ? ec.web.secureRequestParameters.opsJson : context.opsJson || '[]')) } catch (e) { ops = null }
const out = ops == null ? {} : (ec.service.sync().name('org.moqui.calc.CalcServices.edit#CalcDocument').parameters({roomId: context.roomId, ops}).call() || {})
const errors = ops == null ? 'opsJson is not JSON' : (ec.message.hasError() ? ec.message.errorsString : null)
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

const out = ec.service.sync().name('org.moqui.calc.CalcServices.get#CalcCellContent').parameters({roomId: context.roomId, sheet: context.sheet,
    row: context.row, column: context.column}).call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({content: out.content || '', errors})

const out = ec.service.sync().name('org.moqui.calc.CalcServices.save#CalcDocument').parameters({roomId: context.roomId, title: context.title || null,
    definitionId: context.definitionId || null, userGroupId: context.userGroupId || null}).call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors}))

const out = ec.service.sync().name('org.moqui.calc.CalcServices.export#CalcDocument').parameters({roomId: context.roomId}).call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
const xlsx = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
if (errors || !out.contentBytes) ec.web.sendJsonError(404, errors || ec.l10n.localize('Export not found'))
// the terminal saves the file from JSON (moqui-tui's report export)
else if (context.json === 'true') ec.web.sendJsonResponse({contentBase64: StringUtilities.base64Encode(out.contentBytes), contentType: xlsx,
    filename: String(out.filename || 'Workbook.xlsx')})
else ec.web.sendBytesResponse(out.contentBytes, xlsx, false, String(out.filename || 'Workbook.xlsx').replace(/[\\/"\r\n]/g, '_'))

const found = ec.service.sync().name('org.moqui.report.ReportServices.get#Definition').parameters({definitionId: context.definitionId}).call() || {}
// only a CalcGrid document is deleted from here
if (!ec.message.hasError() && found.definition && found.definition.type == 'calcgrid')
    ec.service.sync().name('org.moqui.report.ReportServices.delete#Definition').parameters({definitionId: context.definitionId}).call()
else if (!ec.message.hasError()) ec.message.addError(ec.l10n.localize('Not a CalcGrid document'))
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({errors})

render-mode.text:
${JSON.stringify((() => {
                const name = String(selectedEntity || entityName || '')
                const here = sri.buildUrl('.').path
                if (context.mode === 'calc' || context.definitionId) {
                    const open = context.definitionId ? {definitionId: String(context.definitionId)} : {source: {type: 'entity', entityName: name}}
                    const room = ec.service.sync().name('org.moqui.calc.CalcServices.open#CalcDocument').parameters(open).call() || {}
                    const error = ec.message.hasError() ? ec.message.errorsString : (room.roomId ? null : 'The workbook did not open')
                    ec.message.clearErrors()
                    if (error) return [{t: 'text', id: 'GridError', style: 'error', text: error}]
                    return [{t: 'text', id: 'GridTitle', style: 'h5', text: (room.title || name) + ' · Calc'},
                        {t: 'link', id: 'GridRecords', text: 'Records', url: name ? here + '?entityName=' + encodeURIComponent(name) : here},
                        {t: 'component', id: 'GridSheet', name: 'calcgrid', props: {room, editable: true}}]
                }
                if (!name) return [{t: 'text', id: 'GridChoose', text: 'Name an entity: Data › Grid?entityName=...'}]
                const pageIndex = Math.max(0, parseInt(context.pageIndex || '0', 10) || 0)
                const size = 20
                const call = (service, parameters) => {
                    const out = ec.service.sync().name('org.moqui.dev.DatabaseServices.' + service).parameters(parameters).call() || {}
                    const error = ec.message.hasError() ? ec.message.errorsString : null
                    ec.message.clearErrors()
                    return {out, error}
                }
                const source = {type: 'entity', entityName: name}
                const columns = call('get#DataGridColumns', {source})
                if (columns.error) return [{t: 'text', id: 'GridError', style: 'error', text: columns.error}]
                ec.resource.script('component://tools/template/ToolsRecent.js').record(name)
                const shown = (columns.out.columns || []).slice(0, 8)
                const rows = call('get#DataGridRows', {source, columns: shown.map((column) => column.name), page: pageIndex + 1, size})
                if (rows.error) return [{t: 'text', id: 'GridError', style: 'error', text: rows.error}]
                const data = rows.out.data || []
                const keys = (columns.out.columns || []).filter((column) => column.pk).map((column) => column.name)
                const editable = !!columns.out.entityName && !name.startsWith('DataDocument.')
                const recordUrl = (row) => {
                    let url = sri.buildUrl('../Record').addParameter('selectedEntity', name)
                    for (const key of keys) url = url.addParameter(key, row[key] == null ? '' : String(row[key]))
                    return url.getUrlWithParams()
                }
                const text = (value) => value == null ? '' : typeof value === 'object' ? JSON.stringify(value) : String(value)
                const count = Number(rows.out.last_row || (pageIndex * size + data.length))
                return [{t: 'text', id: 'GridTitle', style: 'h5', text: name},
                    {t: 'link', id: 'GridCalc', text: 'Calc: the rows as a workbook', url: here + '?mode=calc&entityName=' + encodeURIComponent(name)},
                    {t: 'formList', id: 'GridRows', name: 'GridRows', columns: shown.map((column) => ({title: column.title || column.name})).concat(editable ? [{title: ''}] : []),
                        rows: data.map((row, index) => ({id: String(index), cells: shown.map((column) => text(row[column.name]))
                            .concat(editable ? [{t: 'link', id: 'GridEdit' + index, text: 'Edit', url: recordUrl(row), kind: 'anchor'}] : [])})),
                        paging: {index: pageIndex, size, count, maxIndex: Math.max(0, Math.ceil(count / size) - 1),
                            rangeLow: data.length ? pageIndex * size + 1 : 0, rangeHigh: pageIndex * size + data.length}}]
            })())}
